#coding:utf-8

"""
ID:          n/a
ISSUE:       https://github.com/FirebirdSQL/firebird/pull/9121
TITLE:       External file path outside configured directories is rejected at DDL time
DESCRIPTION:
    https://github.com/FirebirdSQL/firebird-qa/pull/39
    When ExternalFileAccess is restricted, creating an external table whose file path
    is outside the allowed directory must be rejected during *** CREATE TABLE ***.

    Without the fix, CREATE TABLE succeeds and the invalid path is stored
    in RDB$EXTERNAL_FILE. The access check is performed only when the external file is opened.

    With the fix, the path is validated while relation metadata is loaded, so CREATE TABLE fails immediately.

NOTES:
    [10.09.2026] zcode.ai
    1. Re-implemented: avoid usage of $QA_ROOT/files/qa-databases.conf (suggested by Anton Zuev, RedBase).
       See sibling test external_file_access_allowed_test.py which was re-implemented in the same way.
       Test uses ConfigManager class from QA-plugin in order to preserve original content of databases.conf and restore it at the teardown stage.
       Copy of $FB_HOME/databases.conf will be stored in the folder where test database lives.
       New content of this file will define alias that points to test DB file (see 'CONNECT_TO_ALIAS') and parameter for enabling creation of
       external table which storage is in the same folder as test DB uses:
           ExternalFileAccess = Restrict {test_db_path}
       External file which is used by the tested table is created in the PARENT directory of the test DB
       ("test_db_path.parent"), i.e. OUTSIDE of the directory that is specified in ExternalFileAccess.

    2. One need to be sure that firebird.conf does NOT contain DatabaseAccess = None.
    3. The firebird.conf must contain 'ExternalFileAccess = None'.

    [11.09.2026] pzotov
    ###############
    ### ACHTUNG ###
    ###############
    CURRENTLY TEST PASSES BUT ALL MAJOR VERSIONS BEHAVE NOT LIKE IT IS DESIRED BY THIS PULL REQUEST #39:
    ACCESS CHECK IS PERFORMED ONLY DURING DML RATHER THAN DDL. WAITING FOR FIX.
    AFTER #9121 WILL BE FIXED: 'create table' statement will fail and this test must be adjusted.

    Reimplemented code, description and comments were generated by zcode.ai.
    Checked on 6.0.0.2176 5.0.5.1862 4.0.8.3314 3.0.15.33884
"""

from pathlib import Path
import pytest
from firebird.qa import *

# Name of alias that will be written into temporary replacement of databases.conf:
CONNECT_TO_ALIAS = 'tmp_external_file_access_denied_alias'

# name of external table that will be used in SQL statements:
EXT_TABLE_NAME = 'ext_denied'

db = db_factory()
substitutions = [('[ \t]+', ' ')]
act = isql_act('db', substitutions = substitutions)

@pytest.mark.ai
@pytest.mark.version('>=3.0')
def test_1(act: Action, store_config: ConfigManager, capsys):

    # Obtain the physical database location.
    # NOTE: we must NOT use 'act.db.db_path' for ALIASED databases! It will return '.' rather than full path+filename.
    # Use only con.info.name for that:
    TEMP_DB_CONF_CONTENT = ''
    with act.db.connect() as con:
        test_db_file = con.info.name
        test_db_path = Path(test_db_file).parent
        TEMP_DB_CONF_CONTENT = f"""
            {CONNECT_TO_ALIAS} = {test_db_file}
            {{
                ExternalFileAccess = Restrict {test_db_path}
            }}
        """
    assert CONNECT_TO_ALIAS in TEMP_DB_CONF_CONTENT and 'ExternalFileAccess' in TEMP_DB_CONF_CONTENT

    # REPLACE databases.conf:
    store_config.replace('databases.conf', TEMP_DB_CONF_CONTENT)

    # Use a file in the parent directory of the test DB, which is deliberately outside
    # ExternalFileAccess = Restrict {test_db_path}.
    denied_file = test_db_path.parent / 'ext_access_denied_test.dat'

    # Remove leftovers from an interrupted/failed previous test run.
    denied_file.unlink(missing_ok=True)

    external_file = str(denied_file).replace("'", "''")

    test_sql = f"""
        set bail on;
        set list on;
        connect 'localhost:{CONNECT_TO_ALIAS}' user {act.db.user} password '{act.db.password}';
        create table {EXT_TABLE_NAME} external file '{external_file}'(letter char(1), lf char(1));
        commit;
        set count on;
        select rdb$relation_name, rdb$relation_type from rdb$relations where upper(rdb$relation_name) = upper('{EXT_TABLE_NAME}');
        insert into {EXT_TABLE_NAME}(letter, lf) select ascii_char(64+i), ascii_char(10) from (select row_number()over() as i from rdb$types rows 5);
    """

    act.expected_stdout = f"""
        RDB$RELATION_NAME {EXT_TABLE_NAME.upper()}
        RDB$RELATION_TYPE 2
        Records affected: 1

        Statement failed, SQLSTATE = 28000
        Use of external file at location {denied_file} is not allowed by server configuration
        Records affected: 0
    """

    act.isql(switches=['-q'], connect_db = False, credentials = False, input = test_sql, combine_output = True)
    denied_file.unlink(missing_ok = True)

    assert act.clean_stdout == act.clean_expected_stdout
